class Niveau:
    def __init__(self, universe, nb_dynamite, goal,source="random", drain="random", duree_source = 150):
        """
        Initialise un niveau avec une source, un drain et une matrice représentant l'univers.

        :param source: Tuple (x, y) représentant la position de la source.
        :param drain: Tuple (x, y) représentant la position du drain.
        :param univers: Liste de listes représentant la matrice de l'univers.
        """
        self.universe = universe
        # add_source_to_universe(universe, source)
        # add_drain_to_universe(universe, drain)
        self.source = source
        self.drain = drain
        self.width = len(universe[0])
        self.height = len(universe)
        self.compteur = 0
        self.time = 0
        self.goal = goal
        self.nb_dynamite = nb_dynamite
        self.duree_source = duree_source

    def afficher_univers(self):
        # Affiche la matrice de l'univers avec la source et le drain marqués.
        for ligne in enumerate(self.universe):
            ligne_affichee = ""
            for case in enumerate(ligne):
                # if (i, j) == self.source:
                #     ligne_affichee += "S "  # Marque la source
                # elif (i, j) == self.drain:
                #     ligne_affichee += "D "  # Marque le drain
                ligne_affichee += f"{case} "
            print(ligne_affichee)

    # def get_source(self):
    #     # Renvoie la position de la source.
    #     return self.source

    # def get_drain(self):
    #     # Renvoie la position du drain.
    #     return self.drain

def get_compteur(self):
        return self.compteur
    

def incr_compteur(self):
        self.compteur += 1

def get_nb_dynamite(self):
        return self.nb_dynamite


def generate_random_niv():
    universe = block_aleatoires((50, 100))
    return Niveau(universe, 3, 100)



